package com.sliit.sparepartshub.stockmonitoring.repository;import com.sliit.sparepartshub.entity.SaleItem;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.time.LocalDateTime;public interface MonitoringSaleItemRepository extends JpaRepository<SaleItem,Integer>{@Query("select coalesce(sum(si.quantity),0) from SaleItem si where si.product.productId=:pid and si.sale.soldAt>=:since")Long sold(@Param("pid")Integer pid,@Param("since")LocalDateTime since);}
